<script setup>
import { computed,ref,nextTick,watch,onMounted } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { Search,ShieldCheck,Image,Paperclip,ArrowRight,Clock3,RefreshCw,MessageCircle,Info,FileText,Send } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import PageTitle from '../components/PageTitle.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { state,orderById,money,uid } from '../lib/store'
import { notify } from '../lib/actions'
const route=useRoute(),router=useRouter(),selected=ref(String(route.query.chat||'merchant')),search=ref(''),text=ref(''),scroll=ref(null)
const conversations=[{id:'official',name:'来单啦通知',initial:'啦',color:'blue',preview:'查看任务与订单的状态通知'},{id:'merchant',name:'青禾美妆',initial:'禾',color:'sand',preview:'任务：护肤新品主图设计 · 5张'},{id:'creator',name:'林间设计',initial:'林',color:'purple',preview:'好的，我再优化下细节。'},{id:'support',name:'来单啦客服',initial:'客',color:'gray',preview:'演示客服会话 · 不会联系真人客服'}]
if(!conversations.some(c=>c.id===selected.value))selected.value='merchant'
const visible=computed(()=>conversations.filter(c=>c.name.includes(search.value))),current=computed(()=>conversations.find(c=>c.id===selected.value)),messages=computed(()=>state.chats[selected.value]||[]),order=computed(()=>state.orders[0]),merchantView=computed(()=>route.query.role==='merchant'||state.session.role==='merchant')
const time=()=>new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})
function bottom(){nextTick(()=>{if(scroll.value)scroll.value.scrollTop=scroll.value.scrollHeight})}
watch(selected,()=>{router.replace({path:'/messages',query:{...route.query,chat:selected.value}});text.value='';bottom()})
onMounted(bottom)
function canSend(){if(!state.session.loggedIn){ElMessage.info('请先登录演示身份后体验消息');router.push({path:'/login',query:{redirect:route.fullPath}});return false}return selected.value!=='official'}
function send(){if(!text.value.trim()||!canSend())return;const body=text.value.trim();if(/1\d{10}|\b(?:vx|wx|qq)\b|加微|威信|微信号|支付宝账号/i.test(body)){state.chats[selected.value].push({mine:false,blocked:true,text:'消息已屏蔽：请在平台内沟通，平台外交易无保障。',at:time()});text.value='';bottom();return}state.chats[selected.value].push({id:uid('MSG'),mine:true,text:body,at:time()});text.value='';bottom()}
function enter(e){if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send()}}
function attach(file){if(!canSend())return;if(file.size>20*1024*1024){ElMessage.warning('聊天附件不能超过 20 MB');return}const isImage=/^image\/(jpeg|png|webp)$/.test(file.raw.type);state.chats[selected.value].push({id:uid('MSG'),mine:true,text:file.name,image:isImage?URL.createObjectURL(file.raw):'',file:!isImage,at:time()});bottom();notify('附件已加入演示会话，未上传或发送到服务器')}
function orderLink(){router.push(merchantView.value?`/merchant/review/${order.value.id}`:`/creator/orders/${order.value.id}`)}
</script>
<template><main id="page-content" class="page-container app-ui messages-page"><PageTitle title="消息中心" description="沟通需求、确认成果、完成交付，让合作始终有迹可循。"/><div :class="['messages-layout',{'is-system-chat':selected==='official'||selected==='support'}]"><aside class="panel conversation-panel"><el-input v-model="search" placeholder="搜索会话" aria-label="搜索会话" clearable><template #prefix><Search :size="17"/></template></el-input><nav aria-label="会话列表"><button v-for="c in visible" :key="c.id" :class="{selected:selected===c.id}" @click="selected=c.id"><span :class="['chat-avatar',c.color]">{{c.initial}}</span><span><strong>{{c.name}}</strong><small>{{c.preview}}</small></span><span v-if="c.id==='official'" class="chat-count" title="通知条数">{{state.chats.official.length}}</span></button></nav><el-empty v-if="!visible.length" :image-size="45" description="没有找到会话"/></aside><section class="panel thread-panel"><header class="thread-heading"><div><h2>{{current.name}}</h2><StatusBadge v-if="selected==='merchant'||selected==='creator'" status="进行中"/></div><el-button v-if="selected==='merchant'||selected==='creator'" link type="primary" @click="orderLink">查看订单<ArrowRight/></el-button></header><div class="info-note warning"><Info/>聊天记录将作为纠纷处理依据，请在平台内沟通。</div><div ref="scroll" class="chat-scroll" role="log" aria-label="演示聊天记录" aria-live="polite"><p class="chat-date">来单啦 · 平台内沟通</p><div v-for="(m,i) in messages" :key="m.id||i" :class="['message-row',{mine:m.mine,blocked:m.blocked}]"><span v-if="!m.blocked" :class="['chat-avatar',m.mine?'blue':current.color]">{{m.mine?'我':current.initial}}</span><div><p v-if="!m.mine&&!m.blocked" class="message-name">{{current.name}}</p><div class="message-bubble"><el-image v-if="m.image" :src="m.image" :preview-src-list="[m.image]" preview-teleported :alt="m.text"/><span v-else><FileText v-if="m.file" :size="17"/>{{m.text}}</span></div><small>{{m.at}}</small></div></div><div class="chat-safety"><ShieldCheck :size="14"/>平台外交易无保障，请勿脱离平台进行交易。</div></div><div v-if="selected!=='official'" class="chat-composer"><div class="quick-replies"><span>快捷回复：</span><button v-for="s in ['收到，我会尽快处理','请查看最新版本']" :key="s" @click="text=s">{{s}}</button></div><div class="compose-row"><div class="attachment-tools"><el-upload :auto-upload="false" :show-file-list="false" accept="image/jpeg,image/png,image/webp" :on-change="attach"><button aria-label="添加聊天图片"><Image :size="22"/></button></el-upload><el-upload :auto-upload="false" :show-file-list="false" :on-change="attach"><button aria-label="添加聊天附件"><Paperclip :size="21"/></button></el-upload></div><el-input v-model="text" type="textarea" :rows="2" resize="none" maxlength="1000" placeholder="输入消息，沟通本次创作需求…" aria-label="消息内容" @keydown="enter"/><el-button type="primary" :disabled="!text.trim()" @click="send">发送</el-button></div><span class="field-help">Enter 发送 · Shift + Enter 换行 · 附件 ≤ 20 MB · 演示会话</span></div><div v-else class="official-note"><ShieldCheck :size="17"/>系统通知会话不支持回复。</div></section><aside v-if="selected==='merchant'||selected==='creator'" class="panel message-context"><h2>任务信息</h2><img src="/assets/task-square/skincare.webp" alt="护肤新品主图参考"/><h3>{{order.title}}</h3><p class="task-message-price">赏金 <strong class="price-text">¥{{money(order.cents)}}</strong></p><div class="data-lines"><div><label><Clock3 :size="15"/> 剩余时间</label><strong>{{order.hours}} 小时</strong></div><div><label><RefreshCw :size="15"/> 免费修改</label><strong>剩余 {{order.remainingRevisions}} 轮</strong></div></div><el-button class="full-button" style="margin-top:25px" @click="orderLink">查看订单<ArrowRight/></el-button><el-button type="primary" class="full-button" style="margin-top:12px" @click="router.push(merchantView?'/merchant/tasks':`/creator/orders/${order.id}`)">{{merchantView?'管理任务':'去交付'}}<ArrowRight/></el-button><p class="field-help">此处为关联订单示例。</p></aside></div></main></template>
<style scoped>.messages-layout{display:grid;grid-template-columns:280px minmax(0,1fr) 285px;gap:14px;min-height:700px}.messages-layout>.panel{margin:0;padding:18px}.conversation-panel>nav{margin:20px -18px 0}.conversation-panel nav>button{display:flex;align-items:center;gap:12px;padding:20px 16px;width:100%;text-align:left;border-bottom:1px solid #edf0f6;position:relative}.conversation-panel nav>button.selected{background:#eaf0ff}.conversation-panel nav>button.selected:before{content:'';position:absolute;top:15px;bottom:15px;left:0;width:3px;background:#002bd7;border-radius:4px}.conversation-panel nav>button>span:nth-child(2){min-width:0;flex:1}.conversation-panel nav strong{display:block;font-size:15px;margin-bottom:5px}.conversation-panel nav small{display:block;font-size:11px;color:#7d889c;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.chat-avatar{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;flex-shrink:0;font-size:19px}.chat-avatar.blue{background:#002bd7;color:#fff}.chat-avatar.sand{background:#c5a47d;color:#fff}.chat-avatar.purple{background:#beb0e8;color:#fff}.chat-avatar.gray{background:#e3e7ef;color:#8391ac}.conversation-panel .chat-count{border-radius:50%;font-size:10px;background:#ff481b;color:#fff;width:18px;height:18px;display:grid;place-items:center}.thread-panel{display:flex;flex-direction:column;min-width:0}.thread-heading{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e6eaf2;padding:2px 0 18px;margin-bottom:14px;gap:10px}.thread-heading>div{display:flex;align-items:center;gap:15px}.thread-heading h2{margin:0;font-size:22px}.thread-panel>.info-note{font-size:12px}.chat-scroll{height:425px;overflow-y:auto;overscroll-behavior:contain;padding:15px 3px;scroll-behavior:smooth}.chat-date{text-align:center;color:#a1aabd;font-size:10px;margin-bottom:20px!important}.message-row{display:flex;gap:10px;align-items:flex-start;margin-bottom:20px}.message-row>div{max-width:82%;min-width:0}.message-name{font-size:11px;color:#8690a1;margin:0 0 5px!important}.message-bubble{background:#f0f2f6;border-radius:0 12px 12px 12px;padding:12px 15px;line-height:1.8;font-size:13px;overflow-wrap:anywhere}.message-bubble .el-image{max-width:100%;width:300px;border-radius:6px;display:block;min-height:80px}.message-bubble :deep(.el-image__inner){max-height:220px;object-fit:cover}.message-bubble>span{display:flex;align-items:center;gap:8px}.message-row small{font-size:9px;color:#9da7b8;display:block;margin:5px 3px}.message-row .chat-avatar{width:34px;height:34px;font-size:14px}.message-row.mine{flex-direction:row-reverse}.mine .message-bubble{background:#e7efff;border-radius:12px 0 12px 12px}.mine small{text-align:right}.chat-safety{display:flex;align-items:center;gap:5px;justify-content:center;background:#f4f5f8;color:#8d96a7;font-size:10px;border-radius:20px;padding:6px 10px;margin:20px auto 5px;width:fit-content}.blocked{justify-content:center}.blocked>div{max-width:95%}.blocked .message-bubble{background:#fff0de;color:#9b641c;font-size:11px}.chat-composer{margin-top:auto;border-top:1px solid #e4e9f1;padding-top:14px}.quick-replies{display:flex;gap:8px;flex-wrap:wrap;font-size:10px;align-items:center;margin-bottom:12px}.quick-replies button{border:1px solid #d5dce7;border-radius:20px;padding:4px 9px;color:#61718c}.quick-replies button:hover{border-color:#002bd7;color:#002bd7}.compose-row{display:flex;gap:10px;align-items:center}.attachment-tools{display:flex;gap:8px;color:#8390a7}.attachment-tools button{display:flex}.compose-row>.el-input{min-width:0;flex:1}.compose-row>.el-button{align-self:stretch;min-width:70px}.message-context>img{width:100%;height:145px;object-fit:cover;object-position:left;border-radius:7px;margin-bottom:18px}.message-context h3{font-size:18px}.task-message-price{font-size:16px;margin:20px 0!important}.task-message-price strong{font-size:27px;margin-left:7px}.message-context .data-lines{font-size:12px}.message-context .data-lines label{display:flex;align-items:center;gap:5px}.official-note{display:flex;align-items:center;justify-content:center;gap:8px;color:#98a2b4;font-size:12px;padding:20px}.messages-page .page-title{margin-bottom:25px}@media(max-width:1300px){.messages-layout{grid-template-columns:225px minmax(0,1fr)}.message-context{display:none}.conversation-panel nav strong{font-size:14px}}@media(max-width:850px){.messages-layout{grid-template-columns:190px minmax(0,1fr)}.messages-layout>.panel{padding:14px}.conversation-panel>nav{margin-left:-14px;margin-right:-14px}.conversation-panel nav>button{padding:16px 12px;gap:8px}.chat-avatar{width:32px;height:32px;font-size:15px}.conversation-panel nav strong{font-size:12px}.thread-heading h2{font-size:18px}.thread-heading .el-button{font-size:11px}.compose-row{flex-wrap:wrap}.compose-row>.el-textarea{flex:1;min-width:120px}.attachment-tools{width:100%}}@media(max-width:650px){.messages-layout{display:flex;flex-direction:column;min-height:0}.conversation-panel>nav{display:flex;overflow-x:auto;margin-top:12px}.conversation-panel nav>button{min-width:145px;border:0;padding:12px}.conversation-panel nav small,.conversation-panel .chat-count{display:none}.thread-panel{min-height:620px}.chat-scroll{height:350px}.thread-heading h2{font-size:17px}.message-bubble{font-size:12px}.chat-safety{font-size:9px}.compose-row{flex-wrap:nowrap}.attachment-tools{width:auto;flex-direction:column}.messages-page .page-title p{font-size:12px}}
</style>
